/** Satır içi SVG simge. $label verilirse ekran okuyucuya okunur, yoksa süs sayılır. */
function icon(string $name, string $class = '', ?string $label = null): string {
    $paths = ICON_PATHS[$name] ?? ICON_PATHS['info'];
    $a11y = $label !== null ? 'role="img" aria-label="' . htmlspecialchars($label, ENT_QUOTES) . '"' : 'aria-hidden="true"';
    return '<svg class="icon' . ($class !== '' ? ' ' . $class : '') . '" ' . $a11y
         . ' viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">'
         . $paths . '</svg>';
}
